        "description": "7月8日，今年第9号台风“巴威”（超强台风级）的中心位于台湾基隆市东偏南方向的洋面上，中心附近最大风力有17级（60米/秒）。台风将逐渐转向西北方向移动，强度变化不大，预计本周末将对中国华东沿海地区造成严重影响。",
